import { describe, expect, test } from "bun:test";
import { render } from "../src/engine.ts";

describe("render", () => {
  test("interpolates and escapes HTML", () => {
    expect(render("Hello, {{user.name}}!", { user: { name: '<A & "B\'>' } })).toBe("Hello, &lt;A &amp; &quot;B&#39;&gt;!");
    expect(render("{{{html}}}", { html: "<b>ok</b>" })).toBe("<b>ok</b>");
  });

  test("preserves text and treats missing values as empty", () => {
    expect(render(" a\n{{missing}}\t b ", {})).toBe(" a\n\t b ");
    expect(render("{{! hidden }}visible", {})).toBe("visible");
  });

  test("handles nested conditionals and defined falsy values", () => {
    const template = "{{#if enabled}}yes {{#if name}}{{name}}{{else}}anon{{/if}}{{else}}no{{/if}}";
    expect(render(template, { enabled: true, name: "Ada" })).toBe("yes Ada");
    expect(render(template, { enabled: false, name: "Ada" })).toBe("no");
    for (const value of ["", 0, false, null, undefined, []]) expect(render("{{#if x}}T{{else}}F{{/if}}", { x: value })).toBe("F");
  });

  test("iterates arrays with scope, index, root fallback, nesting, and else", () => {
    const template = "{{#each rows}}{{@index}}:{{this.name}}/{{title}}[{{#each this.values}}{{this}}-{{@index}};{{/each}}]{{else}}empty{{/each}}";
    expect(render(template, { title: "root", rows: [{ name: "a", values: [1, 2] }, { name: "b", values: [3] }] })).toBe("0:a/root[1-0;2-1;]1:b/root[3-0;]");
    expect(render("{{#each rows}}x{{else}}none{{/each}}", { rows: [] })).toBe("none");
  });

  test("rejects malformed templates and non-scalar output", () => {
    for (const template of ["{{#wat x}}{{/wat}}", "{{#if x}}{{/each}}", "{{#if x}}", "{{else}}", "{{#if x}}{{else}}{{else}}{{/if}}"])
      expect(() => render(template, {})).toThrow(/line 1, column/);
    expect(() => render("{{x}}", { x: {} })).toThrow("Cannot render an object or function as text");
  });
});

